import {Router} from '../framework/router.ts';
export function registerAccounts(router: Router) {
  router.get('/accounts/:id', async (req, res) => {
    if(req.fail) throw new Error('account read');
    return res.send('account:'+req.id);
  });
  router.post('/accounts', async function createAccount(req, res) {
    if(req.fail) throw new Error('account create');
    return res.send('created:'+req.id);
  });
  router.get('/health', (_req,res) => res.send('ok'));
}
export const documentation = "router.get('/fake', async handler)";
export async function unrelatedHelper() { throw new Error('helper'); }
import {Router} from '../framework/router.ts';
const audit = { get(_name: string, callback: () => Promise<string>) { return callback; } };
export const auditCallback = audit.get('orders', async () => { throw new Error('audit'); });
export function registerOrders(router: Router) {
  router.get('/orders/:id', async (req,res) => {
    const values = await Promise.all([req.id].map(async value => value.toUpperCase()));
    if(req.fail) throw new Error('order read');
    return res.send(values[0]);
  });
  router.delete('/orders/:id', async (req,res) => {
    if(req.fail) throw new Error('order delete');
    return res.send('deleted:'+req.id);
  });
}
import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
test('five routes registered',()=>assert.equal(makeRouter().routes.length,5));

